L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "そういう心理を利用して、基地の周りに認知を歪ませる波長を発生させるのよ。"
L21_1.m_Talk_ENG = "We use that psychology, and generate waves that distort their perception around the base."
L21_1.m_Talk_TWN = "利用這種心理，在基地周圍散發了扭曲認知的波長。"
L21_1.m_Talk_SCN = "利用这种心理，在基地周围散发了扭曲认知的波长。"
L21_1.m_Talk_DEU = "We use that psychology, and generate waves that distort their perception around the base."
L21_1.m_Talk_FRA = "We use that psychology, and generate waves that distort their perception around the base."
