L24_1 = {}
L24_1.m_CutScenKey_Talk = "YAKSHA_ACT1_INTERUDE3@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 6400106
L24_1.m_CutScenStrID = "YAKSHA_ACT1_INTERUDE3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L24_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L24_1.m_Pos = "L"
L24_1.m_Talk_KOREA = "그 결과, 이 기지는 실재하지만, 평범한 사람들에게는 실재하지 않는 것처럼 여겨지게 돼."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "おかげでこの基地は実在しながらも普通の人間には認知されないってわけ。"
L24_1.m_Talk_ENG = "As a result, the base exists but it appears not to exist to ordinary people."
L24_1.m_Talk_TWN = "成果就是，這個基地雖然真實存在，但對於普通人來說卻並不存在。"
L24_1.m_Talk_SCN = "成果就是，这个基地虽然真实存在，但对于普通人来说却并不存在。"
L24_1.m_Talk_DEU = "As a result, the base exists but it appears not to exist to ordinary people."
L24_1.m_Talk_FRA = "As a result, the base exists but it appears not to exist to ordinary people."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "YAKSHA_ACT1_INTERUDE3@25#Talk"
L25_1.m_CutScenProcessKey = 25
