L25_1.m_Face = "UNIT_PRIDE"
L25_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "뭐, 음모론에 심취한 괴짜들은 가끔 기지를 발견하기도 하는 모양이지만."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "陰謀論を信じる変わり者に気づかれることは時々あるみたいだけど。"
L25_1.m_Talk_ENG = "Well, some conspiracy theory nerds occasionally seem to discover it from time to time."
L25_1.m_Talk_TWN = "唔，不過似乎有時候也會被某些陰謀論者發現……"
L25_1.m_Talk_SCN = "唔，不过似乎有时候也会被某些阴谋论者发现……"
L25_1.m_Talk_DEU = "Well, some conspiracy theory nerds occasionally seem to discover it from time to time."
L25_1.m_Talk_FRA = "Well, some conspiracy theory nerds occasionally seem to discover it from time to time."
