L15_1.m_Pos = "L"
L16_1 = "동포 중에서는 인외의 특징이 두드러지지 않거나, 그걸 숨길 수 있는 부류도 있는 모양이야."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "同胞の中には、人外の特徴が目立たない人とか、隠せる人もいるみたいよ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It appears that among our compatriots, some have less noticeable external characteristics, or are able to better conceal them."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我們的同伴中，也有一些外在特徵不突出，或者能夠隱藏特徵的人。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "我们的同胞中，也有一些外在特征不突出，或者能够隐藏特征的人。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "It appears that among our compatriots, some have less noticeable external characteristics, or are able to better conceal them."
L15_1.m_Talk_DEU = L16_1
L16_1 = "It appears that among our compatriots, some have less noticeable external characteristics, or are able to better conceal them."
