L17_1 = "하지만 대부분의 동포들은 일반적인 카운터들과 달리 너무 눈에 띄거든."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "でもほとんどは、一般的なカウンターと違って目立ちすぎるの。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But most of our compatriots stand out too much compared to regular Counters."
L16_1.m_Talk_ENG = L17_1
L17_1 = "但是，大多數人與普通制裁者相比顯得太過突出。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "但是，大多数人与普通制裁者相比显得太过特别。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "But most of our compatriots stand out too much compared to regular Counters."
L16_1.m_Talk_DEU = L17_1
L17_1 = "But most of our compatriots stand out too much compared to regular Counters."
L16_1.m_Talk_FRA = L17_1
