L17_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L17_1.m_Pos = "L"
L18_1 = "세계는…… 아직 우리와 같은 별종을 받아들일 준비가 안 됐어."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "世界は……まだ私たちのような他種族を受け入れる準備ができていない。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "This world is... just not ready to accept freaks like us."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這個世界……還沒有準備好接受像我們這樣的異類。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "这个世界……还没有准备好接受像我们这样的异类。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "This world is... just not ready to accept freaks like us."
L17_1.m_Talk_DEU = L18_1
L18_1 = "This world is... just not ready to accept freaks like us."
L17_1.m_Talk_FRA = L18_1
