L20_1 = "관리국은 환상종의 후예들을 외부로부터 보호하고 있다는 건가."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "管理局は幻想種の末裔たちを、外の世界から守っているってわけか。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Is that why the Administration is shielding the descendants of Bygones from the world?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你說管理局在保護夢幻品種後裔免受外界的侵害？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "你说管理局在保护幻想种后裔免受外界的侵害？"
