L22_1.m_Face = "UNIT_IDLE"
L22_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L22_1.m_Pos = "L"
L23_1 = "맞아. 하지만 엄밀히 말하자면 이건 <color=#ffd34c>계약</color>이야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そう。でも厳密に言うとこれは<color=#ffd34c>契約</color>よ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Yes. But technically speaking, this is a <color=#ffd34c>contract</color> we have with them."
L22_1.m_Talk_ENG = L23_1
L23_1 = "沒錯。但嚴格來說，這是<color=#ffd34c>合約</color>。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "没错。但严格来说，这是<color=#ffd34c>契约</color>。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Yes. But technically speaking, this is a <color=#ffd34c>contract</color> we have with them."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Yes. But technically speaking, this is a <color=#ffd34c>contract</color> we have with them."
L22_1.m_Talk_FRA = L23_1
