L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L23_1.m_Pos = "L"
L24_1 = "<color=#ffd34c>세계가 환상종의 존재를 수용할 때까지, 동포들의 삶을 보장한다.</color>"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "<color=#ffd34c>世界が幻想種の存在を受け入れるようになるまで、同胞たちの生活を保障する。</color>"
L23_1.m_Talk_JPN = L24_1
L24_1 = "<color=#ffd34c>Until the world is able to accept the existence of Bygones, we guarantee the safety of your compatriots.</color>"
L23_1.m_Talk_ENG = L24_1
L24_1 = "<color=#ffd34c>保障我們同伴的生命安全，直到世界能夠接受夢幻品種的存在。</color>"
L23_1.m_Talk_TWN = L24_1
L24_1 = "<color=#ffd34c>保障我们同胞的生命安全，直到世界能够接受幻想种的存在。</color>"
L23_1.m_Talk_SCN = L24_1
L24_1 = "<color=#ffd34c>Until the world is able to accept the existence of Bygones, we guarantee the safety of your compatriots.</color>"
L23_1.m_Talk_DEU = L24_1
L24_1 = "<color=#ffd34c>Until the world is able to accept the existence of Bygones, we guarantee the safety of your compatriots.</color>"
L23_1.m_Talk_FRA = L24_1
