L24_1.m_Pos = "L"
L25_1 = "우리 전대장님께서는 그런 조건으로 관리국과 계약해서 야크샤 전대를 설립하셨거든."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "うちの戦隊長は、その条件で管理局と契約し、ヤクシャー戦隊を立ち上げたの。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Our Commander made a deal with the Administration under this condition and established the Yaksha Division."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我們的戰隊長就是因此與管理局簽訂了合約，創立了夜叉戰隊。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "我们的战队长就是因此与管理局签订了契约，创立了夜叉战队。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Our Commander made a deal with the Administration under this condition and established the Yaksha Division."
L24_1.m_Talk_DEU = L25_1
