L26_1.m_Talk_JPN = L27_1
L27_1 = "So, you're a special unit under the Administration, but it wasn't established by the Administration?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "所以，你們是管理局下屬的特種部隊？但不是管理局直接創立的？"
