L30_1 = "아무리 관리국이라고 해도, 인력 부족 문제는 어쩔 수 없거든."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "管理局も人手不足でね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Even the Administration can't do anything about being shorthanded."
L29_1.m_Talk_ENG = L30_1
L30_1 = "就算是管理局，也無法避免人手短缺的問題。"
