L30_1.m_Pos = "L"
L31_1 = "관리국이 필요에 따라, 직접 설립하여 운용하는 전대들도 있지만."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "必要に応じて管理局自ら立ち上げて運営する戦隊もあるけど。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "There are divisions independently established and operated as needed by the Administration."
L30_1.m_Talk_ENG = L31_1
L31_1 = "雖然根據需要，管理局也有直接創立和經營的戰隊。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "虽然根据需要，管理局也有直接创立和运营的战队。"
